function TaskRow({ task, onToggle, onRemove, TK }) {
  const [h,setH]=useState(false);
  const PC={high:"#ef4444",med:"#f59e0b",low:"#10b981"};
  return (
    <div onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)}
      style={{display:"flex",alignItems:"center",gap:10,padding:"10px 14px",borderRadius:10,opacity:task.done?0.55:1,background:h?TK.cardHov:TK.card,border:`1px solid ${TK.border}`,transition:"all 0.18s"}}>
      <button onClick={onToggle} style={{width:18,height:18,borderRadius:4,border:`2px solid ${task.done?TK.dim:PC[task.pri]}`,background:task.done?TK.dim:"transparent",display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,color:"#fff",flexShrink:0,cursor:"pointer"}}>{task.done?"✓":""}</button>
      <div style={{flex:1,fontSize:13,color:TK.text,textDecoration:task.done?"line-through":"none"}}>{task.text}</div>
      <div style={{width:7,height:7,borderRadius:"50%",background:PC[task.pri],flexShrink:0}}/>
      <button onClick={onRemove} style={{color:TK.dim,fontSize:15,background:"none",border:"none",cursor:"pointer",opacity:h?1:0,transition:"opacity 0.15s"}}>×</button>
    </div>
  );
}

function TaskList({ L, TK }) {
  const [tasks,setTasks]=useState(() => {
    const saved = localStorage.getItem('portfolio_tasks');
    if(saved){
      return JSON.parse(saved);
    }
    return [{id:1,text:"Review Next.js 14 docs",done:false,pri:"high"},{id:2,text:"Build component library",done:false,pri:"med"},{id:3,text:"Update portfolio",done:true,pri:"low"}];
  });
  const [input,setInput]=useState(""); 
  const [pri,setPri]=useState("med");
  
  // Save to localStorage whenever tasks change
  useEffect(() => {
    localStorage.setItem('portfolio_tasks', JSON.stringify(tasks));
  }, [tasks]);
  
  const add=()=>{if(!input.trim())return;setTasks(t=>[{id:Date.now(),text:input.trim(),done:false,pri},...t]);setInput("");};
  const toggle=id=>setTasks(t=>t.map(x=>x.id===id?{...x,done:!x.done}:x));
  const remove=id=>setTasks(t=>t.filter(x=>x.id!==id));
  const clearDone=()=>setTasks(t=>t.filter(x=>!x.done));
  const todo=tasks.filter(t=>!t.done),done=tasks.filter(t=>t.done);
  return (
    <div style={{display:"flex",flexDirection:"column",gap:14}}>
      <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:10}}>
        {[{n:tasks.length,l:"Total",c:TK.accent},{n:todo.length,l:"Pending",c:"#f59e0b"},{n:done.length,l:"Done",c:"#10b981"}].map(({n,l,c})=>(
          <div key={l} style={{background:TK.card,border:`1px solid ${TK.border}`,borderRadius:10,padding:12,textAlign:"center"}}>
            <div style={{fontSize:24,fontWeight:800,color:c}}>{n}</div>
            <div style={{fontSize:10,color:TK.muted,letterSpacing:"1px",textTransform:"uppercase",marginTop:2}}>{l}</div>
          </div>
        ))}
      </div>
      <div style={{display:"flex",gap:7}}>
        <input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==="Enter"&&add()} placeholder={L.prod.addTask}
          style={{flex:1,padding:"10px 14px",background:TK.inputBg,border:`1px solid ${TK.border}`,borderRadius:9,color:TK.text,fontSize:13,outline:"none"}}/>
        <select value={pri} onChange={e=>setPri(e.target.value)} style={{padding:"10px 8px",background:TK.inputBg,border:`1px solid ${TK.border}`,borderRadius:9,color:TK.muted,fontSize:12,cursor:"pointer"}}>
          <option value="high">● High</option><option value="med">● Med</option><option value="low">● Low</option>
        </select>
        <Btn onClick={add} baseStyle={{padding:"10px 18px",borderRadius:9,background:TK.accent,color:"#fff",fontSize:13,fontWeight:700}} hov={{background:TK.accentHov}}>{L.prod.add}</Btn>
      </div>
      {tasks.length===0?<div style={{textAlign:"center",padding:28,color:TK.muted,fontSize:14}}>{L.prod.noTasks}</div>
        :<div style={{display:"flex",flexDirection:"column",gap:6,maxHeight:280,overflowY:"auto"}}>
          {[...todo,...done].map(task=><TaskRow key={task.id} task={task} onToggle={()=>toggle(task.id)} onRemove={()=>remove(task.id)} TK={TK}/>)}
        </div>}
      {done.length>0&&<Btn onClick={clearDone} baseStyle={{alignSelf:"center",padding:"6px 16px",borderRadius:20,border:`1px solid ${TK.border}`,background:"transparent",color:TK.muted,fontSize:12}} hov={{color:TK.text,borderColor:TK.borderHov}}>{L.prod.clear} ({done.length})</Btn>}
    </div>
  );
}

