/* ═══════════════════════════════════════════
   PROJECT CARD
═══════════════════════════════════════════ */
function ProjectCard({ p, lang, TK, dark }) {
  const [h,setH]=useState(false);
  const cardRef = useRef(null);
  const [tilt,setTilt]=useState({x:0,y:0});
  const sc=p.status==="Live"?"#22c55e":p.status==="GitHub"?"#64748b":"#f59e0b";
  
  const handleMouseMove = (e) => {
    if(!h || !cardRef.current) return;
    const rect = cardRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const centerX = rect.width / 2;
    const centerY = rect.height / 2;
    const tiltX = ((y - centerY) / centerY) * -5;
    const tiltY = ((x - centerX) / centerX) * 5;
    setTilt({x:tiltX,y:tiltY});
  };
  
  return (
    <a ref={cardRef} href={p.url} 
      onMouseEnter={()=>setH(true)} 
      onMouseLeave={()=>{setH(false);setTilt({x:0,y:0});}}
      onMouseMove={handleMouseMove}
      style={{
        display:"flex",
        flexDirection:"column",
        background:h?TK.cardHov:TK.card,
        border:`1px solid ${h?p.color+"66":TK.border}`,
        borderRadius:18,
        overflow:"hidden",
        transform:h?`translateY(-6px) rotateX(${tilt.x}deg) rotateY(${tilt.y}deg)`:"translateY(0) rotateX(0) rotateY(0)",
        boxShadow:h?`0 20px 48px ${dark?"rgba(0,0,0,0.4)":TK.accentGlow}, 0 0 0 1px ${p.color}33`:"0 4px 12px rgba(0,0,0,0.05)",
        backdropFilter:"blur(8px)",
        textDecoration:"none",
        transition:"all 0.28s cubic-bezier(.23,1,.32,1)",
        transformStyle:"preserve-3d",
        perspective:"1000px",
      }}>
      <div style={{height:160,background:`linear-gradient(135deg,${p.color}22,${p.color}06)`,display:"flex",alignItems:"center",justifyContent:"center",position:"relative",overflow:"hidden"}}>
        <div style={{position:"absolute",inset:0,background:`radial-gradient(circle at 70% 30%,${p.color}28,transparent 65%)`}}/>
        {/* Animated gradient overlay on hover */}
        <div style={{
          position:"absolute",
          inset:0,
          background:`linear-gradient(135deg, ${p.color}33, transparent)`,
          opacity:h?1:0,
          transition:"opacity 0.3s",
        }}/>
        <span style={{fontSize:50,filter:`drop-shadow(0 4px 12px ${p.color}55)`,position:"relative",transform:h?"scale(1.1) translateZ(20px)":"scale(1) translateZ(0)",transition:"transform 0.3s"}}>{p.emoji}</span>
        <div style={{position:"absolute",top:12,right:12,background:sc,color:"#fff",fontSize:9,fontWeight:700,letterSpacing:"1px",textTransform:"uppercase",padding:"3px 9px",borderRadius:20,boxShadow:h?`0 4px 12px ${sc}66`:"none",transition:"box-shadow 0.2s"}}>{p.status}</div>
      </div>
      <div style={{padding:"18px 18px 16px",transform:"translateZ(10px)"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:6}}>
          <div>
            <div style={{fontSize:14,fontWeight:700,color:TK.text,marginBottom:2}}>{p.name[lang]}</div>
            <div style={{fontSize:11,color:TK.accent,fontWeight:600}}>{p.cat[lang]}</div>
          </div>
          <span style={{fontSize:17,color:TK.accent,transform:h?"rotate(-45deg) scale(1.2)":"rotate(0) scale(1)",transition:"transform 0.25s",flexShrink:0}}>↗</span>
        </div>
        <p style={{fontSize:12,color:TK.muted,lineHeight:1.6,marginBottom:10}}>{p.desc[lang]}</p>
        <div style={{display:"flex",flexWrap:"wrap",gap:4}}>
          {p.tech.map(t=><span key={t} style={{fontSize:9,fontWeight:700,color:TK.dim,background:TK.inputBg,border:`1px solid ${TK.border}`,borderRadius:5,padding:"3px 7px",textTransform:"uppercase"}}>{t}</span>)}
        </div>
      </div>
    </a>
  );
}

